/**
 * @name dx.bi
 * @description The dx.bi experience: cinematic billboard, Netflix-style carousels, hover previews, IMDb ratings on posters, wide Continue Watching, stream sorting & filters, a Netflix-style player, a cinematic intro and interface sounds. Use with the dx.bi theme.
 * @version 2.4.0
 * @author dx.bi
 * @updateUrl https://raw.githubusercontent.com/notdxbi/dxbi-stremio/main/dxbi.plugin.js
 */

(function () {
  "use strict";

  if (window.__dxbi && typeof window.__dxbi.destroy === "function") {
    try { window.__dxbi.destroy(); } catch (_) { /* previous instance already gone */ }
  }

  const API = typeof StremioEnhancedAPI !== "undefined" ? StremioEnhancedAPI : null;
  // Stremio Enhanced loads each plugin as <script id="<file name>">, which tells us our settings key
  const SCRIPT_ID = (document.currentScript && document.currentScript.id) || "dxbi.plugin.js";
  const PLUGIN_KEY = SCRIPT_ID.replace(/\.plugin\.js$/, "");
  const log = (...args) => console.log("[dx.bi]", ...args);

  // ---------------------------------------------------------------------------
  // Settings
  // ---------------------------------------------------------------------------

  const ACCENTS = {
    red: "#e50914",
    crimson: "#d81f3c",
    blue: "#2f80ff",
    purple: "#8b5cf6",
    green: "#1db954",
    amber: "#f5a524",
    pink: "#ec4899",
    white: "#f4f4f5",
  };

  const DEFAULTS = {
    accent: "red",
    billboard: true,
    billboardSource: "mixed",
    billboardInterval: "9",
    previews: true,
    ratings: true,
    wideContinue: true,
    playerExtras: true,
    seekPreviews: true,
    remainingTime: true,
    streamTools: true,
    splash: true,
    introSound: true,
    uiSounds: true,
    soundVolume: "subtle",
  };

  const SCHEMA = [
    {
      key: "accent",
      type: "select",
      label: "Accent colour",
      description: "Colour used for the logo, progress bars, seek bar and highlights.",
      defaultValue: DEFAULTS.accent,
      options: [
        { label: "Cinema Red", value: "red" },
        { label: "Crimson", value: "crimson" },
        { label: "Electric Blue", value: "blue" },
        { label: "Violet", value: "purple" },
        { label: "Emerald", value: "green" },
        { label: "Amber", value: "amber" },
        { label: "Pink", value: "pink" },
        { label: "Mono", value: "white" },
      ],
    },
    { key: "billboard", type: "toggle", label: "Billboard on Home", description: "Large rotating feature banner at the top of Home.", defaultValue: DEFAULTS.billboard },
    {
      key: "billboardSource",
      type: "select",
      label: "Billboard content",
      defaultValue: DEFAULTS.billboardSource,
      options: [
        { label: "Popular movies & series", value: "mixed" },
        { label: "Popular movies", value: "movie" },
        { label: "Popular series", value: "series" },
        { label: "Top rated (IMDb)", value: "rated" },
      ],
    },
    {
      key: "billboardInterval",
      type: "select",
      label: "Billboard rotation",
      defaultValue: DEFAULTS.billboardInterval,
      options: [
        { label: "Every 6 seconds", value: "6" },
        { label: "Every 9 seconds", value: "9" },
        { label: "Every 14 seconds", value: "14" },
        { label: "Don't rotate", value: "0" },
      ],
    },
    { key: "previews", type: "toggle", label: "Hover previews", description: "Show a details card when you rest the mouse on a title.", defaultValue: DEFAULTS.previews },
    { key: "ratings", type: "toggle", label: "IMDb ratings on posters", description: "Small IMDb badge on posters, from your addons' data (Cinemeta fills any gaps).", defaultValue: DEFAULTS.ratings },
    { key: "wideContinue", type: "toggle", label: "Wide Continue Watching", description: "Show Continue Watching as landscape cards with title art.", defaultValue: DEFAULTS.wideContinue },
    { key: "playerExtras", type: "toggle", label: "Netflix-style player extras", description: "Back/forward 10 seconds buttons, title in the control bar and play/pause feedback.", defaultValue: DEFAULTS.playerExtras },
    { key: "seekPreviews", type: "toggle", label: "Seek bar previews", description: "Show a thumbnail and time when you point at the progress bar (needs a direct stream; uses a little extra bandwidth).", defaultValue: DEFAULTS.seekPreviews },
    { key: "remainingTime", type: "toggle", label: "Show time remaining", description: "The player clock counts down, like Netflix (click it to switch back).", defaultValue: DEFAULTS.remainingTime },
    { key: "streamTools", type: "toggle", label: "Stream sorting & filters", description: "Sort streams by quality, seeds or size and filter by quality, language, source, provider, instant and HDR.", defaultValue: DEFAULTS.streamTools },
    { key: "splash", type: "toggle", label: "Intro animation", description: "Plays once each time the app starts.", defaultValue: DEFAULTS.splash },
    { key: "introSound", type: "toggle", label: "Intro sound", description: "Play the intro's score (a 'ta-dum', a chord and a whoosh).", defaultValue: DEFAULTS.introSound },
    { key: "uiSounds", type: "toggle", label: "Interface sounds", description: "Soft sounds for tabs, opening titles, previews, My List, player controls and keyboard navigation.", defaultValue: DEFAULTS.uiSounds },
    {
      key: "soundVolume",
      type: "select",
      label: "Sound volume",
      defaultValue: DEFAULTS.soundVolume,
      options: [
        { label: "Subtle", value: "subtle" },
        { label: "Normal", value: "normal" },
        { label: "Loud", value: "loud" },
      ],
    },
  ];

  const settings = { ...DEFAULTS };

  function normalise(raw) {
    const out = { ...DEFAULTS };
    if (!raw || typeof raw !== "object") return out;
    for (const key of Object.keys(DEFAULTS)) {
      if (raw[key] === undefined || raw[key] === null || raw[key] === "") continue;
      if (typeof DEFAULTS[key] === "boolean") out[key] = raw[key] === true || raw[key] === "true";
      else out[key] = String(raw[key]);
    }
    return out;
  }

  async function loadSettings() {
    // Cached copy first so the UI is right on the very first frame
    try { Object.assign(settings, normalise(JSON.parse(localStorage.getItem("dxbi.settings") || "null"))); } catch (_) { /* ignore */ }
    applyAccent();
    if (!API) return;

    // Drop a schema left over from an older version (kept in memory until the app restarts)
    try {
      await window.StremioEnhancedAPI?.clearRegisteredSettings?.(PLUGIN_KEY);
    } catch (_) { /* nothing registered yet */ }
    API.registerSettings(SCHEMA).catch(() => { /* already registered */ });
    const values = await Promise.all(
      Object.keys(DEFAULTS).map((key) => API.getSetting(key).then((v) => [key, v]).catch(() => [key, null]))
    );
    Object.assign(settings, normalise(Object.fromEntries(values)));
    persistSettings();
    API.onSettingsSaved((all) => {
      Object.assign(settings, normalise(all));
      persistSettings();
      applyAccent();
      hero.reset();
      scheduleSync();
    });
  }

  function persistSettings() {
    try { localStorage.setItem("dxbi.settings", JSON.stringify(settings)); } catch (_) { /* ignore */ }
  }

  function applyAccent() {
    const colour = ACCENTS[settings.accent] || ACCENTS.red;
    document.documentElement.style.setProperty("--dx-accent", colour);
  }

  // ---------------------------------------------------------------------------
  // Helpers
  // ---------------------------------------------------------------------------

  const ICONS = {
    play: '<svg viewBox="0 0 24 24" aria-hidden="true"><path d="M7 4.5v15a1 1 0 0 0 1.53.85l12-7.5a1 1 0 0 0 0-1.7l-12-7.5A1 1 0 0 0 7 4.5z"/></svg>',
    info: '<svg viewBox="0 0 24 24" aria-hidden="true" stroke-width="2" stroke-linecap="round"><circle cx="12" cy="12" r="9.25"/><path d="M12 11v6M12 7.5v.01"/></svg>',
    chevronDown: '<svg viewBox="0 0 24 24" aria-hidden="true" fill="none" stroke="currentColor" stroke-width="2.4" stroke-linecap="round" stroke-linejoin="round"><path d="M6 9l6 6 6-6"/></svg>',
    chevronLeft: '<svg viewBox="0 0 24 24" aria-hidden="true" fill="none" stroke="currentColor" stroke-width="2.6" stroke-linecap="round" stroke-linejoin="round"><path d="M15 5l-7 7 7 7"/></svg>',
    chevronRight: '<svg viewBox="0 0 24 24" aria-hidden="true" fill="none" stroke="currentColor" stroke-width="2.6" stroke-linecap="round" stroke-linejoin="round"><path d="M9 5l7 7-7 7"/></svg>',
    nextEp: '<svg viewBox="0 0 24 24" aria-hidden="true" fill="currentColor"><path d="M5 4.8v14.4a.8.8 0 0 0 1.25.66L16 13.3V19a1 1 0 0 0 2 0V5a1 1 0 0 0-2 0v5.7L6.25 4.14A.8.8 0 0 0 5 4.8z"/></svg>',
    sort: '<svg viewBox="0 0 24 24" aria-hidden="true" fill="none" stroke="currentColor" stroke-width="2.2" stroke-linecap="round" stroke-linejoin="round"><path d="M7 4v16M3.5 16.5L7 20l3.5-3.5M17 20V4M13.5 7.5L17 4l3.5 3.5"/></svg>',
    pause: '<svg viewBox="0 0 24 24" aria-hidden="true" fill="currentColor"><rect x="5.5" y="4" width="4.5" height="16" rx="1"/><rect x="14" y="4" width="4.5" height="16" rx="1"/></svg>',
    plus: '<svg viewBox="0 0 24 24" aria-hidden="true" fill="none" stroke="currentColor" stroke-width="2.4" stroke-linecap="round"><path d="M12 5v14M5 12h14"/></svg>',
    check: '<svg viewBox="0 0 24 24" aria-hidden="true" fill="none" stroke="currentColor" stroke-width="2.6" stroke-linecap="round" stroke-linejoin="round"><path d="M5 12.5l4.5 4.5L19 7.5"/></svg>',
    rewind10: '<svg viewBox="0 0 24 24" aria-hidden="true" fill="none" stroke="currentColor" stroke-width="1.9" stroke-linecap="round" stroke-linejoin="round"><path d="M4.5 12a7.5 7.5 0 1 0 2.2-5.3"/><path d="M6.7 2.8v3.9h3.9"/><text x="12" y="14.7" text-anchor="middle" fill="currentColor" stroke="none" style="font: 800 6.4px Inter, sans-serif; letter-spacing: -0.3px">10</text></svg>',
    forward10: '<svg viewBox="0 0 24 24" aria-hidden="true" fill="none" stroke="currentColor" stroke-width="1.9" stroke-linecap="round" stroke-linejoin="round"><path d="M19.5 12a7.5 7.5 0 1 1-2.2-5.3"/><path d="M17.3 2.8v3.9h-3.9"/><text x="12" y="14.7" text-anchor="middle" fill="currentColor" stroke="none" style="font: 800 6.4px Inter, sans-serif; letter-spacing: -0.3px">10</text></svg>',
    playSmall: '<svg viewBox="0 0 24 24" aria-hidden="true" fill="currentColor"><path d="M8 5.2v13.6a.8.8 0 0 0 1.22.68l10.8-6.8a.8.8 0 0 0 0-1.36L9.22 4.52A.8.8 0 0 0 8 5.2z"/></svg>',
  };

  const esc = (s) => String(s ?? "").replace(/[&<>"']/g, (c) => ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;", "'": "&#39;" }[c]));

  const art = {
    background: (id) => `https://images.metahub.space/background/large/${id}/img`,
    backgroundMedium: (id) => `https://images.metahub.space/background/medium/${id}/img`,
    logo: (id) => `https://images.metahub.space/logo/medium/${id}/img`,
  };

  function parseDetailHref(href) {
    const m = /#\/detail\/([^/]+)\/([^/?]+)/.exec(href || "");
    if (!m) return null;
    return { type: decodeURIComponent(m[1]), id: decodeURIComponent(m[2]) };
  }

  function cardInfo(card) {
    const link = card.querySelector('a[class*="meta-item-link"]') || card.querySelector("a[href]");
    if (!link) return null;
    const href = link.getAttribute("href") || "";
    const parsed = parseDetailHref(href);
    if (!parsed) return null;
    const title = card.querySelector('[class*="title-label"]')?.textContent?.trim() || link.getAttribute("title") || "";
    const poster = card.querySelector('img[class*="poster-image"]')?.getAttribute("src") || "";
    return { ...parsed, href, title, poster, link };
  }

  function isImdb(id) {
    return /^tt\d+$/.test(id || "");
  }

  function preload(url) {
    return new Promise((resolve) => {
      const img = new Image();
      img.onload = () => resolve(true);
      img.onerror = () => resolve(false);
      img.src = url;
    });
  }

  function formatRuntime(runtime) {
    if (!runtime) return "";
    const mins = parseInt(String(runtime).replace(/[^\d]/g, ""), 10);
    if (!mins) return String(runtime);
    if (mins < 60) return `${mins}m`;
    return `${Math.floor(mins / 60)}h ${mins % 60 ? (mins % 60) + "m" : ""}`.trim();
  }

  function imdbHtml(rating) {
    const r = parseFloat(rating);
    if (!r) return "";
    return `<span class="dx-imdb"><i>IMDb</i>${r.toFixed(1)}</span>`;
  }

  // ---------------------------------------------------------------------------
  // Metadata (Cinemeta) with memory + localStorage cache and a small fetch queue
  // ---------------------------------------------------------------------------

  const META_TTL = 3 * 24 * 60 * 60 * 1000;
  const META_PREFIX = "dxbi.meta.";
  const memory = new Map();
  const inflight = new Map();
  const queue = [];
  let active = 0;

  function readCached(key) {
    if (memory.has(key)) return memory.get(key);
    try {
      const raw = localStorage.getItem(META_PREFIX + key);
      if (!raw) return undefined;
      const entry = JSON.parse(raw);
      if (Date.now() - entry.t > META_TTL) return undefined;
      memory.set(key, entry.m);
      return entry.m;
    } catch (_) {
      return undefined;
    }
  }

  let writes = 0;
  function writeCached(key, meta) {
    memory.set(key, meta);
    if (memory.size > 1500) memory.delete(memory.keys().next().value);
    try {
      localStorage.setItem(META_PREFIX + key, JSON.stringify({ t: Date.now(), m: meta }));
      if (++writes % 50 === 0) pruneCache(900);
    } catch (_) {
      pruneCache(0);
    }
  }

  // Keep the cache bounded: drop expired entries, then the oldest beyond `limit`
  function pruneCache(limit) {
    try {
      const entries = [];
      for (const k of Object.keys(localStorage)) {
        if (!k.startsWith(META_PREFIX)) continue;
        let t = 0;
        try { t = JSON.parse(localStorage.getItem(k)).t || 0; } catch (_) { /* corrupt entry */ }
        if (Date.now() - t > META_TTL) localStorage.removeItem(k);
        else entries.push([k, t]);
      }
      const keep = limit || Math.floor(entries.length / 2);
      entries.sort((a, b) => a[1] - b[1]);
      entries.slice(0, Math.max(0, entries.length - keep)).forEach(([k]) => localStorage.removeItem(k));
    } catch (_) { /* ignore */ }
  }

  function slimMeta(meta) {
    if (!meta) return null;
    return {
      name: meta.name,
      type: meta.type,
      imdbRating: meta.imdbRating,
      releaseInfo: meta.releaseInfo || meta.year,
      runtime: meta.runtime,
      genres: (meta.genres || meta.genre || []).slice(0, 4),
      seasons: Array.isArray(meta.videos) ? new Set(meta.videos.map((v) => v.season).filter((n) => n > 0)).size : 0,
      description: meta.description ? String(meta.description).slice(0, 420) : "",
      logo: meta.logo,
      background: meta.background,
    };
  }

  function getMeta(type, id) {
    if (!isImdb(id) || (type !== "movie" && type !== "series")) return Promise.resolve(null);
    const key = `${type}:${id}`;
    const cached = readCached(key);
    if (cached !== undefined) return Promise.resolve(cached);
    if (inflight.has(key)) return inflight.get(key);
    const p = new Promise((resolve) => {
      queue.push({ type, id, key, resolve });
      pump();
    });
    inflight.set(key, p);
    return p;
  }

  function pump() {
    while (active < 4 && queue.length) {
      const job = queue.shift();
      active++;
      fetch(`https://v3-cinemeta.strem.io/meta/${job.type}/${job.id}.json`, { signal: AbortSignal.timeout(10000) })
        .then((r) => (r.ok ? r.json() : null))
        .then((j) => {
          const meta = slimMeta(j && j.meta);
          if (meta) writeCached(job.key, meta);
          job.resolve(meta);
        })
        .catch(() => job.resolve(null))
        .finally(() => {
          active--;
          inflight.delete(job.key);
          pump();
        });
    }
  }

  // ---------------------------------------------------------------------------
  // Route + header state
  // ---------------------------------------------------------------------------

  function currentRoute() {
    const hash = (location.hash || "#/").replace(/^#/, "");
    const first = hash.split(/[/?]/).filter(Boolean)[0] || "board";
    return first;
  }

  function updateRoute() {
    const route = currentRoute();
    if (document.body.dataset.dxRoute !== route) {
      document.body.dataset.dxRoute = route;
      document.body.classList.remove("dx-scrolled");
      preview.close(true);
    }
  }

  function onScroll(event) {
    const target = event.target;
    if (!(target instanceof Element)) return;
    preview.close(true);
    if (target.matches('[class*="board-content-"]:not([class*="board-content-container"]), [class*="discover-content"] [class*="meta-items-container"], [class*="library-content"] [class*="meta-items-container"], [class*="search-content"], [class*="settings-content"] [class*="sections-container"], [class*="addons-list-container"], [class*="calendar"] [class*="content"]')) {
      document.body.classList.toggle("dx-scrolled", target.scrollTop > 8);
    }
    if (target.matches('[class*="meta-row"] > [class*="meta-items-container"]')) {
      updateArrows(target.parentElement);
    }
  }

  // ---------------------------------------------------------------------------
  // Billboard
  // ---------------------------------------------------------------------------

  const hero = {
    el: null,
    items: [],
    index: 0,
    timer: null,
    loading: null,
    stalled: false,

    sourceUrls() {
      const base = "https://v3-cinemeta.strem.io/catalog";
      switch (settings.billboardSource) {
        case "movie": return [`${base}/movie/top.json`];
        case "series": return [`${base}/series/top.json`];
        case "rated": return [`${base}/movie/imdbRating.json`, `${base}/series/imdbRating.json`];
        default: return [`${base}/movie/top.json`, `${base}/series/top.json`];
      }
    },

    async load() {
      if (this.loading) return this.loading;
      this.loading = (async () => {
        const lists = await Promise.all(
          this.sourceUrls().map((u) =>
            fetch(u, { signal: AbortSignal.timeout(10000) })
              .then((r) => (r.ok ? r.json() : { metas: [] }))
              .then((j) => j.metas || [])
              .catch(() => [])
          )
        );
        // Interleave movies and series, keep ones with real artwork and a description
        const merged = [];
        const max = Math.max(...lists.map((l) => l.length), 0);
        for (let i = 0; i < max && merged.length < 24; i++) {
          for (const list of lists) if (list[i]) merged.push(list[i]);
        }
        const usable = merged.filter((m) => isImdb(m.id) && m.description && (m.background || m.poster)).slice(0, 8);
        // Only keep slides whose backdrop actually loads
        const checked = await Promise.all(usable.map(async (m) => ((await preload(art.background(m.id))) ? m : null)));
        this.items = checked.filter(Boolean).slice(0, 6);
        return this.items;
      })();
      return this.loading;
    },

    host() {
      return document.querySelector('[class*="board-container"] [class*="board-content-"]:not([class*="board-content-container"])');
    },

    async ensure() {
      const host = this.host();
      if (!settings.billboard || !host) {
        if (!settings.billboard) this.remove();
        return;
      }
      if (this.el && this.el.isConnected && host.firstElementChild === this.el) {
        this.resumeIfStalled();
        return;
      }
      if (this.el && this.el.isConnected && host.contains(this.el)) {
        host.insertBefore(this.el, host.firstElementChild);
        return;
      }
      if (!this.items.length) {
        await this.load();
        if (!this.items.length) return;
      }
      const freshHost = this.host();
      if (!freshHost || (this.el && this.el.isConnected)) return;
      this.build();
      freshHost.insertBefore(this.el, freshHost.firstElementChild);
      this.show(this.index % this.items.length, true);
    },

    build() {
      const el = document.createElement("section");
      el.className = "dx-hero";
      el.setAttribute("aria-label", "Featured");
      el.innerHTML =
        this.items.map((m, i) => this.slideHtml(m, i)).join("") +
        `<div class="dx-hero-shade"></div>` +
        `<div class="dx-hero-dots">${this.items.map((m, i) => `<button class="dx-hero-dot" data-i="${i}" aria-label="${esc(m.name)}"></button>`).join("")}</div>`;
      const interval = parseInt(settings.billboardInterval, 10);
      el.style.setProperty("--dx-hero-interval", (interval || 9) + "s");
      if (!interval) el.classList.add("is-static");

      el.addEventListener("click", (e) => {
        const dot = e.target.closest(".dx-hero-dot");
        if (dot) { this.show(parseInt(dot.dataset.i, 10)); return; }
        const go = e.target.closest("[data-href]");
        if (go) location.hash = go.dataset.href;
      });

      el.querySelectorAll(".dx-hero-logo").forEach((img) => {
        img.addEventListener("error", () => {
          const title = document.createElement("h1");
          title.className = "dx-hero-title";
          title.textContent = img.alt;
          img.replaceWith(title);
        }, { once: true });
      });
      this.el = el;
    },

    slideHtml(m, i) {
      const type = m.type === "series" ? "series" : "movie";
      const year = m.releaseInfo ? String(m.releaseInfo).replace(/–$/, "–") : "";
      const genres = (m.genres || m.genre || []).slice(0, 3);
      const metaBits = [
        imdbHtml(m.imdbRating),
        year && `<span>${esc(year)}</span>`,
        m.runtime && `<span>${esc(formatRuntime(m.runtime))}</span>`,
        `<span class="dx-pill">${type === "series" ? "Series" : "Film"}</span>`,
        genres.length && `<span>${genres.map(esc).join(" · ")}</span>`,
      ].filter(Boolean);
      const playHref = type === "movie" ? `/detail/movie/${m.id}/${m.id}` : `/detail/series/${m.id}`;
      return `
        <div class="dx-hero-slide" data-i="${i}">
          <div class="dx-hero-backdrop" style="background-image:url('${art.background(m.id)}')"></div>
          <div class="dx-hero-content">
            <div class="dx-hero-kicker"><b>DX.BI</b>${type === "series" ? "Series" : "Film"}</div>
            <img class="dx-hero-logo" src="${art.logo(m.id)}" alt="${esc(m.name)}" draggable="false">
            <div class="dx-hero-meta">${metaBits.join("")}</div>
            <p class="dx-hero-desc">${esc(m.description)}</p>
            <div class="dx-hero-actions">
              <button class="dx-btn dx-btn-primary" data-href="${playHref}">${ICONS.play}<span>Play</span></button>
              <button class="dx-btn dx-btn-secondary" data-href="/detail/${type}/${m.id}">${ICONS.info}<span>More Info</span></button>
            </div>
          </div>
        </div>`;
    },

    show(i, instant) {
      if (!this.el || !this.items.length) return;
      this.index = (i + this.items.length) % this.items.length;
      this.el.classList.toggle("is-first", !!instant);
      this.el.querySelectorAll(".dx-hero-slide").forEach((slide, n) => {
        const backdrop = slide.querySelector(".dx-hero-backdrop");
        if (n === this.index) {
          clearTimeout(backdrop._kbOff);
          if (!slide.classList.contains("is-active")) {
            backdrop.classList.remove("kb");
            void backdrop.offsetWidth; // restart the slow zoom from the beginning
            backdrop.classList.add("kb");
          }
          slide.classList.add("is-active");
        } else if (slide.classList.contains("is-active")) {
          slide.classList.remove("is-active");
          // keep zooming while it fades out, then reset quietly
          backdrop._kbOff = setTimeout(() => backdrop.classList.remove("kb"), 1400);
        }
      });
      this.el.querySelectorAll(".dx-hero-dot").forEach((d, n) => {
        d.classList.remove("is-active");
        if (n === this.index) {
          void d.offsetWidth; // restart the progress animation
          d.classList.add("is-active");
        }
      });
      if (!instant) preload(art.background(this.items[(this.index + 1) % this.items.length].id));
      this.schedule();
    },

    schedule() {
      clearTimeout(this.timer);
      const seconds = parseInt(settings.billboardInterval, 10);
      if (!seconds || this.items.length < 2) return;
      this.timer = setTimeout(() => this.tick(), seconds * 1000);
    },

    tick() {
      const visible = this.el && this.el.isConnected && currentRoute() === "board" && !document.hidden;
      if (!visible) {
        // Off screen: stop here and resume with a fresh slide when Home is visible again
        this.stalled = true;
        return;
      }
      this.show(this.index + 1);
    },

    resumeIfStalled() {
      if (this.stalled && this.el && this.el.isConnected && currentRoute() === "board" && !document.hidden) {
        this.stalled = false;
        this.show(this.index + 1);
      }
    },

    remove() {
      clearTimeout(this.timer);
      if (this.el) this.el.remove();
      this.el = null;
    },

    reset() {
      this.remove();
      this.items = [];
      this.loading = null;
      this.index = 0;
      scheduleSync();
    },
  };

  // ---------------------------------------------------------------------------
  // Carousels (arrows + page dots)
  // ---------------------------------------------------------------------------

  function carouselRows() {
    return document.querySelectorAll('[class*="board-content-"]:not([class*="board-content-container"]) [class*="meta-row-container"], [class*="search-content"] [class*="meta-row-container"]');
  }

  function enhanceRow(row) {
    const track = row.querySelector(':scope > [class*="meta-items-container"]');
    if (!track) return;
    if (!row.querySelector(":scope > .dx-arrow")) {
      const prev = document.createElement("button");
      prev.className = "dx-arrow dx-arrow-prev is-hidden";
      prev.setAttribute("aria-label", "Previous");
      prev.innerHTML = ICONS.chevronLeft;
      const next = document.createElement("button");
      next.className = "dx-arrow dx-arrow-next";
      next.setAttribute("aria-label", "Next");
      next.innerHTML = ICONS.chevronRight;
      const pages = document.createElement("div");
      pages.className = "dx-row-pages";
      prev.addEventListener("click", () => page(row, -1));
      next.addEventListener("click", () => page(row, 1));
      row.append(prev, next, pages);
    }
    updateArrows(row);
  }

  function page(row, dir) {
    const track = row.querySelector(':scope > [class*="meta-items-container"]');
    if (!track) return;
    const first = track.querySelector(':scope > [class*="meta-item"]');
    const step = first ? first.getBoundingClientRect().width : 200;
    const perPage = Math.max(1, Math.floor((track.clientWidth - 40) / step));
    track.scrollBy({ left: dir * perPage * step, behavior: "smooth" });
  }

  function updateArrows(row) {
    const track = row && row.querySelector(':scope > [class*="meta-items-container"]');
    if (!track) return;
    const max = track.scrollWidth - track.clientWidth;
    const prev = row.querySelector(":scope > .dx-arrow-prev");
    const next = row.querySelector(":scope > .dx-arrow-next");
    const pages = row.querySelector(":scope > .dx-row-pages");
    if (!prev || !next || !pages) return;
    prev.classList.toggle("is-hidden", track.scrollLeft <= 4);
    next.classList.toggle("is-hidden", track.scrollLeft >= max - 4);
    // Arrows cover the cards exactly, whatever the row height
    const top = track.offsetTop;
    const height = track.offsetHeight;
    for (const a of [prev, next]) {
      a.style.top = top + "px";
      a.style.height = height + "px";
      a.style.bottom = "auto";
    }
    const count = max > 4 ? Math.ceil(track.scrollWidth / track.clientWidth) : 0;
    if (pages.childElementCount !== count) pages.innerHTML = "<span></span>".repeat(count);
    if (count) {
      const activePage = Math.round((track.scrollLeft / max) * (count - 1));
      [...pages.children].forEach((s, i) => s.classList.toggle("is-active", i === activePage));
    }
  }

  // ---------------------------------------------------------------------------
  // Metadata from the user's own addons (via Stremio's core state), so previews, ratings and
  // My List work for every catalog — TMDB, anime, streaming catalogs — not just Cinemeta.
  // ---------------------------------------------------------------------------

  const coreMeta = {
    map: new Map(),
    at: 0,
    loading: null,
    MODELS: ["board", "discover", "search", "library", "continue_watching_preview"],

    refresh(force) {
      if (!window.core || typeof window.core.getState !== "function") return Promise.resolve();
      if (!force && Date.now() - this.at < 4000) return this.loading || Promise.resolve();
      this.at = Date.now();
      this.loading = (async () => {
        for (const model of this.MODELS) {
          try { this.collect(await window.core.getState(model), 0); } catch (_) { /* model not loaded yet */ }
        }
      })();
      return this.loading;
    },

    // Walk a state tree and remember anything that looks like a title
    collect(node, depth) {
      if (!node || typeof node !== "object" || depth > 7) return;
      if (Array.isArray(node)) {
        for (const item of node) this.collect(item, depth + 1);
        return;
      }
      const id = node.id || node._id;
      if (typeof id === "string" && typeof node.type === "string" && typeof node.name === "string" && ("poster" in node || "posterShape" in node)) {
        this.remember(id, node);
        return;
      }
      for (const value of Object.values(node)) {
        if (value && typeof value === "object") this.collect(value, depth + 1);
      }
    },

    remember(id, item) {
      const links = Array.isArray(item.links) ? item.links : [];
      const imdbLink = links.find((l) => l && l.category === "imdb");
      const imdbFromUrl = imdbLink && /tt\d+/.exec(imdbLink.url || "");
      const rating = imdbLink && parseFloat(imdbLink.name);
      const genres = links.filter((l) => l && l.category === "Genres").map((l) => l.name).slice(0, 4);
      const key = `${item.type}:${id}`;
      const prev = this.map.get(key) || {};
      this.map.set(key, {
        name: item.name || prev.name,
        description: item.description || prev.description || "",
        releaseInfo: item.releaseInfo || prev.releaseInfo || "",
        runtime: item.runtime || prev.runtime || "",
        genres: genres.length ? genres : prev.genres || [],
        imdbRating: rating || prev.imdbRating || null,
        imdbId: isImdb(id) ? id : (imdbFromUrl ? imdbFromUrl[0] : prev.imdbId || null),
        background: item.background || prev.background || null,
        logo: item.logo || prev.logo || null,
        poster: item.poster || prev.poster || null,
        inLibrary: typeof item.inLibrary === "boolean" ? item.inLibrary : prev.inLibrary,
      });
    },

    get(type, id) {
      return this.map.get(`${type}:${id}`) || null;
    },
  };

  // Posters that already print a rating on the artwork — don't add a second one
  const RATED_POSTER = /ratingposterdb|\/rpdb\/|top-?posters|toppostersapi|easyratings|ratings?[-_]?posters?/i;

  // Everything we know about a title: the addon's own data first, Cinemeta fills the gaps
  async function getInfo(type, id) {
    await coreMeta.refresh();
    const fromAddon = coreMeta.get(type, id);
    const imdbId = isImdb(id) ? id : fromAddon && fromAddon.imdbId;
    let info = fromAddon ? { ...fromAddon } : {};
    const missing = !info.imdbRating || !(info.genres && info.genres.length) || !info.releaseInfo;
    if (imdbId && missing) {
      const cinemeta = await getMeta(type, imdbId);
      if (cinemeta) {
        for (const [k, v] of Object.entries(cinemeta)) {
          const have = info[k];
          if (have === undefined || have === null || have === "" || (Array.isArray(have) && !have.length)) info[k] = v;
        }
      }
    }
    info.imdbId = imdbId || null;
    return info;
  }

  // Artwork for a title: addon-provided first, then MetaHub via its IMDb id
  function artFor(info, id, kind) {
    const imdbId = isImdb(id) ? id : info && info.imdbId;
    if (kind === "background") return (info && info.background) || (imdbId ? art.backgroundMedium(imdbId) : null);
    if (kind === "logo") return (info && info.logo) || (imdbId ? art.logo(imdbId) : null);
    return null;
  }

  // ---------------------------------------------------------------------------
  // Poster decorations: IMDb badge + wide Continue Watching art
  // ---------------------------------------------------------------------------

  const io = new IntersectionObserver(
    (entries) => {
      for (const entry of entries) {
        if (!entry.isIntersecting) continue;
        io.unobserve(entry.target);
        decorate(entry.target);
      }
    },
    { rootMargin: "300px 600px" }
  );

  function allCards() {
    return document.querySelectorAll('#app [class*="meta-item-container"]');
  }

  function isWideRow(card) {
    return settings.wideContinue && !!card.closest('[class*="continue-watching-row"]');
  }

  function decorate(card) {
    const info = cardInfo(card);
    const poster = card.querySelector('[class*="poster-container"]');
    if (!info || !poster) return;
    const key = `${info.type}:${info.id}`;
    const known = coreMeta.get(info.type, info.id);

    // Wide art for Continue Watching
    const wantWide = isWideRow(card);
    let wide = poster.querySelector(":scope > .dx-wide-art");
    if (wantWide) {
      if (!wide || wide.dataset.key !== key) {
        if (wide) wide.remove();
        wide = document.createElement("div");
        wide.className = "dx-wide-art";
        wide.dataset.key = key;
        const target = wide;
        const fallback = info.poster ? `url('${info.poster}')` : "none";
        const useFallback = () => {
          target.classList.add("is-fallback");
          target.innerHTML =
            (info.poster ? `<div class="dx-wide-blur" style="background-image:${fallback}"></div><img class="dx-wide-thumb" alt="" src="${esc(info.poster)}">` : "") +
            `<div class="dx-wide-name">${esc(info.title)}</div>`;
        };
        const paint = (meta) => {
          const bg = artFor(meta, info.id, "background");
          const logoUrl = artFor(meta, info.id, "logo");
          if (!bg) { useFallback(); return; }
          preload(bg).then((ok) => {
            if (!target.isConnected) return;
            if (!ok) { useFallback(); return; }
            target.style.backgroundImage = `url('${bg}')`;
            target.innerHTML = logoUrl ? `<img class="dx-wide-logo" alt="" src="${esc(logoUrl)}">` : `<div class="dx-wide-name">${esc(info.title)}</div>`;
            target.querySelector(".dx-wide-logo")?.addEventListener("error", (ev) => {
              ev.target.replaceWith(Object.assign(document.createElement("div"), { className: "dx-wide-name", textContent: info.title }));
            }, { once: true });
          });
        };
        if (known || isImdb(info.id)) paint(known);
        else getInfo(info.type, info.id).then(paint);
        poster.prepend(wide);
      }
    } else if (wide) {
      wide.remove();
    }

    // IMDb rating badge (posters only, and never on artwork that already shows a rating)
    let badge = poster.querySelector(":scope > .dx-badge");
    if (!settings.ratings || wantWide || RATED_POSTER.test(info.poster)) {
      if (badge) badge.remove();
      return;
    }
    if (badge && badge.dataset.key === key) return;
    if (badge) badge.remove();
    const place = (value) => {
      const rating = parseFloat(value);
      const current = cardInfo(card);
      if (!rating || !current || `${current.type}:${current.id}` !== key) return;
      if (poster.querySelector(":scope > .dx-badge")) return;
      const b = document.createElement("div");
      b.className = "dx-badge";
      b.dataset.key = key;
      b.innerHTML = `<i>IMDb</i>${rating.toFixed(1)}`;
      poster.append(b);
    };
    if (known && known.imdbRating) place(known.imdbRating);
    else getInfo(info.type, info.id).then((meta) => meta && meta.imdbRating && place(meta.imdbRating));
  }

  function syncCards() {
    coreMeta.refresh();
    for (const card of allCards()) {
      const info = cardInfo(card);
      const key = info ? `${info.type}:${info.id}` : "";
      if (card.dataset.dxKey === key && card.dataset.dxWide === String(isWideRow(card)) && card.dataset.dxRatings === String(settings.ratings)) continue;
      card.dataset.dxKey = key;
      card.dataset.dxWide = String(isWideRow(card));
      card.dataset.dxRatings = String(settings.ratings);
      io.unobserve(card);
      io.observe(card);
    }
  }

  // ---------------------------------------------------------------------------
  // Hover preview card
  // ---------------------------------------------------------------------------

  const preview = {
    el: null,
    card: null,
    openTimer: null,
    closeTimer: null,
    token: 0,
    library: { ids: new Set(), at: 0 },

    eligible(card) {
      if (!settings.previews) return false;
      if (!card.closest('[class*="board-content-"]:not([class*="board-content-container"]), [class*="search-content"], [class*="library-content"]')) return false;
      return !!cardInfo(card);
    },

    onOver(e) {
      const card = e.target.closest && e.target.closest('[class*="meta-item-container"]');
      if (!card) return;
      if (card === this.card) {
        clearTimeout(this.closeTimer);
        return;
      }
      if (!this.eligible(card)) return;
      clearTimeout(this.openTimer);
      const warm = this.el && this.el.classList.contains("is-open");
      this.openTimer = setTimeout(() => {
        if (card.isConnected && card.matches(":hover")) this.open(card);
      }, warm ? 160 : 600);
    },

    onOut(e) {
      const card = e.target.closest && e.target.closest('[class*="meta-item-container"]');
      if (card && !card.contains(e.relatedTarget)) clearTimeout(this.openTimer);
    },

    ensureEl() {
      if (this.el && this.el.isConnected) return this.el;
      const el = document.createElement("div");
      el.className = "dx-preview";
      el.addEventListener("mouseleave", () => this.scheduleClose());
      el.addEventListener("mouseenter", () => clearTimeout(this.closeTimer));
      el.addEventListener("click", (e) => {
        const list = e.target.closest("[data-list]");
        if (list) {
          this.toggleList(list);
          return;
        }
        const go = e.target.closest("[data-href]");
        if (go) {
          this.close(true);
          location.hash = go.dataset.href;
        }
      });
      document.body.append(el);
      this.el = el;
      return el;
    },

    async refreshLibrary() {
      if (Date.now() - this.library.at < 15000 || !window.core || !window.core.getState) return;
      this.library.at = Date.now();
      try {
        const state = await window.core.getState("library");
        this.library.ids = new Set((state.catalog || []).map((i) => i._id || i.id));
      } catch (_) { /* library not available — the button still works */ }
    },

    toggleList(button) {
      if (!window.core || !window.core.dispatch) return;
      const { id, type, name, poster } = button.dataset;
      const inList = this.library.ids.has(id);
      try {
        window.core.dispatch({
          action: "Ctx",
          args: inList
            ? { action: "RemoveFromLibrary", args: id }
            : { action: "AddToLibrary", args: { id, type, name, poster: poster || null, posterShape: "poster" } },
        });
      } catch (err) {
        log("library update failed", err);
        return;
      }
      if (inList) this.library.ids.delete(id);
      else this.library.ids.add(id);
      sfx.play(inList ? "remove" : "confirm");
      this.paintList(button);
      button.classList.remove("is-pop");
      void button.offsetWidth;
      button.classList.add("is-pop");
    },

    paintList(button) {
      const on = this.library.ids.has(button.dataset.id);
      button.innerHTML = on ? ICONS.check : ICONS.plus;
      button.setAttribute("aria-label", on ? "Remove from My List" : "Add to My List");
      button.dataset.tip = on ? "Remove from My List" : "Add to My List";
    },

    render(info, meta) {
      const name = meta.name || info.title;
      const href = info.href.replace(/^#/, "");
      const playHref = info.type === "movie" ? `/detail/movie/${info.id}/${info.id}` : href;
      const bg = artFor(meta, info.id, "background");
      const logoUrl = artFor(meta, info.id, "logo");
      const media = [bg && `url('${bg}')`, info.poster && `url('${info.poster}')`].filter(Boolean).join(", ") || "none";
      const rating = parseFloat(meta.imdbRating);
      const length = info.type === "series"
        ? (meta.seasons ? `${meta.seasons} Season${meta.seasons > 1 ? "s" : ""}` : "")
        : formatRuntime(meta.runtime);
      const facts = [
        rating ? `<span class="dx-match">${rating.toFixed(1)} IMDb</span>` : "",
        meta.releaseInfo ? `<span>${esc(String(meta.releaseInfo).replace(/–$/, "–now"))}</span>` : "",
        length ? `<span>${esc(length)}</span>` : "",
        `<span class="dx-hd">HD</span>`,
      ].join("");
      const genres = (meta.genres || []).slice(0, 3);
      return `
        <div class="dx-preview-media" data-href="${esc(href)}" style="background-image:${media}">
          ${logoUrl ? `<img alt="" src="${esc(logoUrl)}">` : ""}
          <div class="dx-preview-name">${esc(name)}</div>
        </div>
        <div class="dx-preview-body">
          <div class="dx-preview-actions">
            <button class="dx-round is-primary" data-href="${esc(playHref)}" aria-label="Play" data-tip="Play">${ICONS.playSmall}</button>
            <button class="dx-round" data-list data-id="${esc(info.id)}" data-type="${esc(info.type)}" data-name="${esc(name)}" data-poster="${esc(info.poster)}"></button>
            <button class="dx-round is-end" data-href="${esc(href)}" aria-label="More info" data-tip="Episodes &amp; info">${ICONS.chevronDown}</button>
          </div>
          <div class="dx-preview-facts">${facts}</div>
          ${genres.length ? `<div class="dx-preview-genres">${genres.map((g) => `<span>${esc(g)}</span>`).join("")}</div>` : ""}
        </div>`;
    },

    async open(card) {
      const info = cardInfo(card);
      if (!info) return;
      const token = ++this.token;
      this.card = card;
      const el = this.ensureEl();
      this.refreshLibrary();

      // Don't keep the user waiting on a slow network: show what we have after 900ms
      const metaPromise = getInfo(info.type, info.id);
      const meta = (await Promise.race([metaPromise, new Promise((r) => setTimeout(() => r(undefined), 900))])) || coreMeta.get(info.type, info.id) || {};
      if (token !== this.token || !card.isConnected || !card.matches(":hover")) return;
      // Stremio knows whether it's already in the library
      if (typeof meta.inLibrary === "boolean") {
        if (meta.inLibrary) this.library.ids.add(info.id);
        else this.library.ids.delete(info.id);
      }

      el.innerHTML = this.render(info, meta);
      this.wire(el);
      if (!meta.imdbRating || !meta.genres || !meta.genres.length) {
        metaPromise.then((late) => {
          if (late && token === this.token && this.el.classList.contains("is-open")) {
            el.innerHTML = this.render(info, late);
            this.wire(el);
          }
        });
      }

      // Final geometry: wider than the card, centred on it, always fully on screen
      const rect = (card.querySelector('[class*="poster-container"]') || card).getBoundingClientRect();
      const rem = parseFloat(getComputedStyle(document.documentElement).fontSize) || 16;
      // Wide enough that its height covers a tall poster (Netflix tiles are landscape, ours are 2:3)
      const width = Math.round(Math.min(Math.max(rect.width * 1.72, 19 * rem), 30 * rem));
      el.classList.remove("is-open", "is-closing");
      el.style.transition = "none";
      el.style.width = width + "px";
      el.style.minHeight = Math.min(Math.ceil(rect.height), window.innerHeight - 24) + "px";
      el.style.left = "0px";
      el.style.top = "0px";
      el.style.transform = "none";
      el.style.visibility = "hidden";
      const height = el.offsetHeight;
      const margin = 12;
      const navBottom = 4.25 * rem + 8;
      let left = rect.left + rect.width / 2 - width / 2;
      left = Math.max(margin, Math.min(left, window.innerWidth - width - margin));
      let top = rect.top + rect.height / 2 - height / 2;
      top = Math.max(navBottom, Math.min(top, window.innerHeight - height - margin));
      el.style.left = Math.round(left) + "px";
      el.style.top = Math.round(top) + "px";

      // Start exactly over the card, then grow into place
      const scale = rect.width / width;
      const startX = rect.left - left;
      const startY = rect.top + rect.height / 2 - (height * scale) / 2 - top;
      el.style.transformOrigin = "0 0";
      el.style.transform = `translate(${startX}px, ${startY}px) scale(${scale})`;
      el.style.visibility = "";
      void el.offsetWidth;
      el.style.transition = "";
      requestAnimationFrame(() => {
        if (token !== this.token) return;
        el.classList.add("is-open");
        el.style.transform = "none";
        sfx.play("pop", 0.9);
      });

      clearTimeout(this.closeTimer);
      if (!this._leave) {
        this._leave = (ev) => {
          if (this.el && this.el.contains(ev.relatedTarget)) return;
          this.scheduleClose();
        };
      }
      card.addEventListener("mouseleave", this._leave);
    },

    wire(el) {
      el.querySelector(".dx-preview-media img")?.addEventListener("load", (ev) => {
        ev.target.closest(".dx-preview-media")?.classList.add("has-logo");
      }, { once: true });
      el.querySelector(".dx-preview-media img")?.addEventListener("error", (ev) => ev.target.remove(), { once: true });
      const list = el.querySelector("[data-list]");
      if (list) this.paintList(list);
    },

    scheduleClose() {
      clearTimeout(this.closeTimer);
      this.closeTimer = setTimeout(() => {
        if (this.el && this.el.matches(":hover")) return;
        this.close();
      }, 120);
    },

    close(immediate) {
      clearTimeout(this.openTimer);
      clearTimeout(this.closeTimer);
      this.token++;
      if (this.card && this._leave) this.card.removeEventListener("mouseleave", this._leave);
      this.card = null;
      if (!this.el || !this.el.classList.contains("is-open")) return;
      const el = this.el;
      el.classList.remove("is-open");
      if (immediate) {
        el.style.transition = "none";
        el.style.visibility = "hidden";
        el.classList.remove("is-closing");
        return;
      }
      el.classList.add("is-closing");
      setTimeout(() => el.classList.remove("is-closing"), 200);
    },
  };

  // ---------------------------------------------------------------------------
  // Player: ±10s, centred title, play/pause feedback
  // ---------------------------------------------------------------------------

  const player = {
    video: null,
    flashTimer: null,

    root() {
      return document.querySelector('[class*="player-container"]');
    },

    ensure() {
      if (!settings.playerExtras || currentRoute() !== "player") {
        this.detach();
        return;
      }
      const root = this.root();
      if (!root) return;
      const row = root.querySelector('[class*="control-bar-buttons-container"]');
      if (row && !row.querySelector(":scope > .dx-seek-back")) {
        row.append(this.seekButton(-1), this.seekButton(1));
      }
      // Next Episode (series only) — uses Stremio's own "play next" shortcut
      const parts = (location.hash || "").split("/");
      const isSeries = decodeURIComponent(parts[5] || "") === "series";
      const next = row && row.querySelector(":scope > .dx-next");
      if (row && isSeries && !next) {
        const b = document.createElement("div");
        b.className = "dx-seek dx-next";
        b.title = "Next episode";
        b.setAttribute("role", "button");
        b.innerHTML = ICONS.nextEp;
        b.addEventListener("click", (e) => {
          e.stopPropagation();
          const opts = { key: "N", code: "KeyN", shiftKey: true, bubbles: true };
          document.dispatchEvent(new KeyboardEvent("keydown", opts));
          document.dispatchEvent(new KeyboardEvent("keyup", opts));
        });
        row.append(b);
      } else if (next && !isSeries) {
        next.remove();
      }

      const source = root.querySelector('[class*="player-title"]:not([class*="container"])');
      const text = (source && source.textContent.trim()) || "";
      if (row && text) {
        let title = row.querySelector(":scope > .dx-player-title");
        if (!title) {
          title = document.createElement("div");
          title.className = "dx-player-title";
          row.append(title);
        }
        if (title.dataset.text !== text) {
          title.dataset.text = text;
          const cut = text.indexOf(" - ");
          const main = cut > 0 ? text.slice(0, cut) : text;
          const rest = cut > 0 ? text.slice(cut + 3) : "";
          title.innerHTML = `<b>${esc(main)}</b>${rest ? `<span>${esc(rest)}</span>` : ""}`;
        }
      }

      if (!root.querySelector(":scope > .dx-player-flash")) {
        const flash = document.createElement("div");
        flash.className = "dx-player-flash";
        root.append(flash);
      }

      const video = root.querySelector("video");
      if (video !== this.video) {
        this.detach();
        if (video) {
          this.video = video;
          video.addEventListener("play", this.onPlay);
          video.addEventListener("pause", this.onPause);
        }
      }
    },

    seekButton(dir) {
      const b = document.createElement("div");
      b.className = `dx-seek ${dir < 0 ? "dx-seek-back" : "dx-seek-fwd"}`;
      b.title = dir < 0 ? "Back 10 seconds" : "Forward 10 seconds";
      b.setAttribute("role", "button");
      b.innerHTML = dir < 0 ? ICONS.rewind10 : ICONS.forward10;
      b.addEventListener("click", (e) => {
        e.stopPropagation();
        const code = dir < 0 ? "ArrowLeft" : "ArrowRight";
        document.dispatchEvent(new KeyboardEvent("keydown", { key: code, code, bubbles: true }));
        document.dispatchEvent(new KeyboardEvent("keyup", { key: code, code, bubbles: true }));
        this.flash(dir < 0 ? ICONS.rewind10 : ICONS.forward10);
      });
      return b;
    },

    flash(icon) {
      const el = this.root()?.querySelector(":scope > .dx-player-flash");
      if (!el) return;
      el.innerHTML = icon;
      el.classList.remove("is-on");
      void el.offsetWidth;
      el.classList.add("is-on");
    },

    onPlay: () => {
      if (player.video && player.video.currentTime > 0.5) {
        player.flash(ICONS.play);
        sfx.play("play");
      }
    },

    onPause: () => {
      if (player.video && !player.video.ended && !player.video.seeking) {
        player.flash(ICONS.pause);
        sfx.play("pause");
      }
    },

    detach() {
      if (this.video) {
        this.video.removeEventListener("play", this.onPlay);
        this.video.removeEventListener("pause", this.onPause);
      }
      this.video = null;
    },
  };

  // ---------------------------------------------------------------------------
  // Splash + window title
  // ---------------------------------------------------------------------------

  // Intro: a pre-rendered 4-second film (AV1, embedded at the bottom of this file). Video is decoded
  // off the main thread, so it stays perfectly smooth while the app boots behind it.
  const SPLASH_READY = '[class*="meta-item-container"], [class*="metadetails-container"], [class*="player-container"], [class*="settings-content"], [class*="addons-content"]';

  function splash() {
    let shown = false;
    try { shown = sessionStorage.getItem("dxbi.splash") === "1"; sessionStorage.setItem("dxbi.splash", "1"); } catch (_) { /* ignore */ }
    if (shown || !settings.splash) return;
    if (window.matchMedia && window.matchMedia("(prefers-reduced-motion: reduce)").matches) return;

    const el = document.createElement("div");
    el.className = "dx-splash";
    document.body.append(el);

    let url = null;
    let done = false;
    const cleanup = () => {
      document.removeEventListener("keydown", onKey, true);
      if (url) URL.revokeObjectURL(url);
    };
    const reveal = () => {
      el.classList.add("is-done");
      setTimeout(() => { el.remove(); cleanup(); }, 650);
    };
    const finish = () => {
      if (done) return;
      done = true;
      if (document.querySelector(SPLASH_READY)) { reveal(); return; }
      // Hold on black until the app has something to show (never more than 4s)
      const since = Date.now();
      const wait = setInterval(() => {
        if (document.querySelector(SPLASH_READY) || Date.now() - since > 4000) {
          clearInterval(wait);
          reveal();
        }
      }, 100);
    };
    const onKey = (e) => {
      if (e.key === "Escape" || e.key === "Enter" || e.key === " ") {
        e.preventDefault();
        e.stopPropagation();
        finish();
      }
    };
    document.addEventListener("keydown", onKey, true);
    el.addEventListener("click", finish);
    setTimeout(finish, 7500); // safety net

    const fallback = () => {
      // Simple, compositor-only animation if video playback isn't available
      el.innerHTML = '<div class="dx-splash-mark">DX.BI</div>';
      setTimeout(finish, 1700);
    };

    const video = document.createElement("video");
    video.className = "dx-splash-video";
    video.muted = !settings.introSound;
    video.playsInline = true;
    video.preload = "auto";
    video.setAttribute("aria-hidden", "true");
    video.style.filter = accentFilter();
    if (!video.canPlayType('video/webm; codecs="av01.0.09M.10, opus"')) {
      fallback();
      return;
    }
    try {
      const bytes = Uint8Array.from(atob(introVideoData()), (c) => c.charCodeAt(0));
      url = URL.createObjectURL(new Blob([bytes], { type: "video/webm" }));
    } catch (_) {
      fallback();
      return;
    }
    video.src = url;
    video.addEventListener("ended", finish, { once: true });
    video.addEventListener("error", () => { if (!done) fallback(); }, { once: true });
    el.append(video);
    video.play().catch(() => {
      // Sound not allowed? Try silently, then give up gracefully
      video.muted = true;
      video.play().catch(() => { if (!done) fallback(); });
    });
  }

  // The intro is rendered in red; shift it to the chosen accent colour
  function accentFilter() {
    if (settings.accent === "white") return "grayscale(1) brightness(1.5)";
    const hex = ACCENTS[settings.accent] || ACCENTS.red;
    const hue = (h) => {
      const [r, g, b] = [1, 3, 5].map((i) => parseInt(h.slice(i, i + 2), 16) / 255);
      const max = Math.max(r, g, b);
      const min = Math.min(r, g, b);
      if (max === min) return 0;
      const d = max - min;
      let x = max === r ? (g - b) / d + (g < b ? 6 : 0) : max === g ? (b - r) / d + 2 : (r - g) / d + 4;
      return x * 60;
    };
    const shift = Math.round(hue(hex) - hue(ACCENTS.red));
    return shift ? `hue-rotate(${shift}deg)` : "none";
  }

  function brandTitle() {
    // The player keeps Stremio's own title: other plugins read it to label the stream
    if (currentRoute() === "player") return;
    const current = document.title || "";
    if (current === "dx.bi" || current.endsWith(" · dx.bi")) return;
    const page = current.replace(/\s*[-–|]?\s*Stremio.*$/i, "").replace(/^web\.stremio\.com$/i, "").trim();
    document.title = page ? `${page} · dx.bi` : "dx.bi";
  }

  // ---------------------------------------------------------------------------
  // Streams: sort + filter bar above the streams list. Reads what any addon writes
  // (quality, size, seeds, flags, provider, debrid status) — no addon-specific setup.
  // Items are reordered with CSS `order` and hidden with an attribute, never moved,
  // so Stremio can keep adding streams as addons answer.
  // ---------------------------------------------------------------------------

  const FLAG_LANG = {
    GB: "English", US: "English", AU: "English", CA: "English", IE: "English", NZ: "English",
    IT: "Italian", ES: "Spanish", MX: "Spanish (Latino)", AR: "Spanish (Latino)", CO: "Spanish (Latino)", CL: "Spanish (Latino)",
    FR: "French", BE: "French", DE: "German", AT: "German", CH: "German", RU: "Russian", UA: "Ukrainian",
    PT: "Portuguese", BR: "Portuguese (Brazil)", JP: "Japanese", KR: "Korean", CN: "Chinese", TW: "Chinese", HK: "Chinese",
    IN: "Hindi", PL: "Polish", NL: "Dutch", TR: "Turkish", SE: "Swedish", NO: "Norwegian", DK: "Danish", FI: "Finnish",
    CZ: "Czech", SK: "Slovak", HU: "Hungarian", GR: "Greek", RO: "Romanian", BG: "Bulgarian", RS: "Serbian", HR: "Croatian",
    SI: "Slovenian", IL: "Hebrew", SA: "Arabic", AE: "Arabic", EG: "Arabic", TH: "Thai", VN: "Vietnamese", ID: "Indonesian",
    MY: "Malay", PH: "Filipino", IR: "Persian", LT: "Lithuanian", LV: "Latvian", EE: "Estonian",
  };
  const LANG_WORDS = [
    [/\bmulti(?:[ .-]?audio|[ .-]?lang)?\b/i, "Multi audio"],
    [/\bdual[ .-]?audio\b/i, "Dual audio"],
    [/\benglish\b/i, "English"], [/\bitalian[oa]?\b/i, "Italian"], [/\b(?:french|truefrench|vff|vfq)\b/i, "French"],
    [/\b(?:german|deutsch)\b/i, "German"], [/\b(?:spanish|castellano|espa[nñ]ol)\b/i, "Spanish"], [/\blatino\b/i, "Spanish (Latino)"],
    [/\brussian\b/i, "Russian"], [/\bhindi\b/i, "Hindi"], [/\bjapanese\b/i, "Japanese"], [/\bkorean\b/i, "Korean"],
    [/\bportugu[eê]se?\b/i, "Portuguese"], [/\bpolish\b/i, "Polish"], [/\bturkish\b/i, "Turkish"], [/\barabic\b/i, "Arabic"],
  ];
  const QUALITY_LABEL = { 2160: "4K", 1440: "1440p", 1080: "1080p", 720: "720p", 480: "SD", 0: "Unknown" };
  const SOURCE_RANK = { Remux: 4, BluRay: 3, WEB: 2, HDTV: 1, Other: 0, CAM: -10 };
  const SORTS = [
    ["default", "Addon order"],
    ["quality", "Best quality"],
    ["seeds", "Most seeds"],
    ["size-desc", "Largest first"],
    ["size-asc", "Smallest first"],
  ];

  function parseStream(el) {
    const nameEl = el.querySelector('[class*="addon-name"]');
    const name = ((nameEl && nameEl.innerText) || "").trim();
    const all = el.innerText || "";
    const firstLine = name.split("\n")[0].trim() || "Unknown";
    const bracket = /^\s*\[([^\]]+)\]/.exec(firstLine);
    const provider = firstLine.replace(/^\s*\[[^\]]*\]\s*/, "").trim() || firstLine;
    const instant = (bracket && /\+|⚡|instant|cached/i.test(bracket[1])) || /⚡|\binstant\b|\bcached\b/i.test(firstLine);

    let res = 0;
    if (/\b(?:2160p|4k|uhd)\b/i.test(all)) res = 2160;
    else if (/\b1440p\b/i.test(all)) res = 1440;
    else if (/\b(?:1080p|fhd)\b/i.test(all)) res = 1080;
    else if (/\b720p\b/i.test(all)) res = 720;
    else if (/\b(?:576p|480p|360p|sd|dvdrip|xvid)\b/i.test(all)) res = 480;

    const dv = /\b(?:dv|dovi|dolby[ .-]?vision)\b/i.test(all);
    const hdr = dv || /\bhdr(?:10\+?)?\b/i.test(all);

    let size = 0;
    const sm = /(\d+(?:[.,]\d+)?)\s*(TB|GB|MB)\b/i.exec(all);
    if (sm) size = parseFloat(sm[1].replace(",", ".")) * { TB: 1e12, GB: 1e9, MB: 1e6 }[sm[2].toUpperCase()];

    const seedMatch = /👤\s*(\d+)/u.exec(all) || /🌱\s*(\d+)/u.exec(all) || /\bseed(?:er)?s?\W{0,3}(\d+)/i.exec(all) || /(\d+)\s*seed/i.exec(all);
    const seeds = seedMatch ? parseInt(seedMatch[1], 10) : -1;

    let source = "Other";
    if (/\bremux\b/i.test(all)) source = "Remux";
    else if (/\b(?:blu-?ray|bdrip|brrip|bdremux|bd25|bd50)\b/i.test(all)) source = "BluRay";
    else if (/\bweb[ .-]?(?:dl|rip)?\b/i.test(all)) source = "WEB";
    else if (/\bhdtv\b/i.test(all)) source = "HDTV";
    else if (/\b(?:cam|hdcam|camrip|telesync|hdts|ts|tc)\b/i.test(all)) source = "CAM";

    const langs = new Set();
    for (const m of all.matchAll(/([\u{1F1E6}-\u{1F1FF}])([\u{1F1E6}-\u{1F1FF}])/gu)) {
      const code = String.fromCharCode(m[1].codePointAt(0) - 0x1f1e6 + 65, m[2].codePointAt(0) - 0x1f1e6 + 65);
      langs.add(FLAG_LANG[code] || code);
    }
    for (const [re, label] of LANG_WORDS) if (re.test(all)) langs.add(label);
    if (!langs.size) langs.add("Not listed (usually English)");

    return { provider, instant, res, hdr, dv, size, seeds, source, langs: [...langs] };
  }

  const streamTools = {
    cache: new WeakMap(),
    state: (() => {
      const base = { sort: "default", quality: [], lang: [], source: [], provider: [], instant: false, hdr: false };
      try { return { ...base, ...JSON.parse(localStorage.getItem("dxbi.streams") || "{}") }; } catch (_) { return base; }
    })(),
    open: null,
    sig: "",

    save() {
      try { localStorage.setItem("dxbi.streams", JSON.stringify(this.state)); } catch (_) { /* ignore */ }
    },

    data(el) {
      const sig = el.textContent.length;
      const hit = this.cache.get(el);
      if (hit && hit.sig === sig) return hit.data;
      const data = parseStream(el);
      this.cache.set(el, { sig, data });
      return data;
    },

    ensure() {
      const panel = document.querySelector('[class*="metadetails-content"] [class*="streams-list-container"]');
      const list = panel && panel.querySelector(':scope > [class*="streams-container"]');
      let bar = panel && panel.querySelector(":scope > .dx-streambar");
      if (!settings.streamTools || !list || !list.offsetParent) {
        if (bar) bar.remove();
        if (list) this.reset(list);
        return;
      }
      const items = [...list.querySelectorAll(':scope > [class*="stream-container"]')];
      if (items.length < 3) {
        if (bar) bar.hidden = true;
        this.reset(list);
        return;
      }
      if (!bar) {
        bar = this.build();
        panel.insertBefore(bar, list);
      }
      bar.hidden = false;
      list.classList.add("dx-sortable");
      const rows = items.map((el) => [el, this.data(el)]);
      this.apply(list, rows, bar);
    },

    reset(list) {
      list.classList.remove("dx-sortable");
      for (const el of list.querySelectorAll(':scope > [class*="stream-container"]')) {
        el.style.order = "";
        el.removeAttribute("data-dx-hide");
      }
      list.parentElement?.querySelector(":scope > .dx-stream-empty")?.remove();
    },

    // What filter values exist in this list (with counts)
    facets(rows) {
      const count = (key) => {
        const map = new Map();
        for (const [, d] of rows) for (const v of [].concat(d[key])) map.set(v, (map.get(v) || 0) + 1);
        return map;
      };
      const quality = count("res");
      return {
        quality: [2160, 1440, 1080, 720, 480, 0].filter((q) => quality.has(q)).map((q) => [String(q), QUALITY_LABEL[q], quality.get(q)]),
        lang: [...count("langs")].sort((a, b) => (a[0] === "Not listed (usually English)") - (b[0] === "Not listed (usually English)") || b[1] - a[1]).map(([v, n]) => [v, v, n]),
        source: Object.keys(SOURCE_RANK).map((s) => [s, s === "WEB" ? "WEB-DL / WEBRip" : s, count("source").get(s)]).filter((x) => x[2]),
        provider: [...count("provider")].sort((a, b) => b[1] - a[1]).map(([v, n]) => [v, v, n]),
        instant: rows.filter(([, d]) => d.instant).length,
        hdr: rows.filter(([, d]) => d.hdr).length,
      };
    },

    matches(d) {
      const s = this.state;
      if (s.quality.length && !s.quality.includes(String(d.res))) return false;
      if (s.source.length && !s.source.includes(d.source)) return false;
      if (s.provider.length && !s.provider.includes(d.provider)) return false;
      if (s.lang.length && !d.langs.some((l) => s.lang.includes(l))) return false;
      if (s.instant && !d.instant) return false;
      if (s.hdr && !d.hdr) return false;
      return true;
    },

    score(d) {
      return d.res * 10 + (d.dv ? 3 : d.hdr ? 2 : 0) + (SOURCE_RANK[d.source] || 0);
    },

    apply(list, rows, bar) {
      const s = this.state;
      // Ignore saved choices that don't exist in this title's streams (keeps old preferences from hiding everything)
      const f = this.facets(rows);
      const present = (key, values) => values.filter((v) => f[key].some(([x]) => x === v));
      const active = {
        quality: present("quality", s.quality), lang: present("lang", s.lang),
        source: present("source", s.source), provider: present("provider", s.provider),
      };
      const saved = { ...s };
      Object.assign(s, active);
      s.instant = saved.instant && f.instant > 0;
      s.hdr = saved.hdr && f.hdr > 0;

      const ranked = rows.map(([el, d], i) => ({ el, d, i, keep: this.matches(d) }));
      const by = {
        quality: (a, b) => this.score(b.d) - this.score(a.d) || (b.d.instant - a.d.instant) || b.d.seeds - a.d.seeds || b.d.size - a.d.size,
        seeds: (a, b) => b.d.seeds - a.d.seeds || this.score(b.d) - this.score(a.d),
        "size-desc": (a, b) => b.d.size - a.d.size,
        "size-asc": (a, b) => (a.d.size || Infinity) - (b.d.size || Infinity),
      }[s.sort];
      const order = by ? [...ranked].sort((a, b) => by(a, b) || a.i - b.i) : ranked;
      order.forEach((r, pos) => {
        const o = by ? String(pos) : "";
        if (r.el.style.order !== o) r.el.style.order = o;
        if (r.keep) r.el.removeAttribute("data-dx-hide");
        else r.el.setAttribute("data-dx-hide", "");
      });
      const shown = ranked.filter((r) => r.keep).length;

      // restore the user's full saved preferences (we only narrowed them for this title)
      Object.assign(this.state, saved);

      const sig = JSON.stringify([f, active, s.sort, s.instant, s.hdr, shown, rows.length]);
      if (sig !== this.sig || !bar.firstChild) {
        this.sig = sig;
        this.renderBar(bar, f, active, shown, rows.length);
      }

      let empty = list.parentElement.querySelector(":scope > .dx-stream-empty");
      if (!shown) {
        if (!empty) {
          empty = document.createElement("div");
          empty.className = "dx-stream-empty";
          empty.innerHTML = 'No streams match these filters.<button type="button" data-act="reset">Clear filters</button>';
          list.parentElement.insertBefore(empty, list);
        }
      } else if (empty) {
        empty.remove();
      }
    },

    build() {
      const bar = document.createElement("div");
      bar.className = "dx-streambar";
      bar.addEventListener("click", (e) => this.onClick(e));
      return bar;
    },

    renderBar(bar, f, active, shown, total) {
      const s = this.state;
      const chip = (key, label, values, count) => {
        const on = values.length > 0;
        const text = on ? (values.length === 1 ? values[0] : `${label} · ${values.length}`) : label;
        return `<button type="button" class="dx-sb-btn${on ? " is-on" : ""}${this.open === key ? " is-open" : ""}" data-menu="${key}">${esc(text)}${ICONS.chevronDown}</button>`;
      };
      const label = (key, v) => (f[key].find(([x]) => x === v) || [, v])[1];
      const sortLabel = (SORTS.find(([k]) => k === s.sort) || SORTS[0])[1];
      let html = `<div class="dx-sb-row">`;
      html += `<button type="button" class="dx-sb-btn dx-sb-sort${this.open === "sort" ? " is-open" : ""}" data-menu="sort">${ICONS.sort}${esc(sortLabel)}${ICONS.chevronDown}</button>`;
      html += `<span class="dx-sb-div"></span>`;
      if (f.quality.length > 1) html += chip("quality", "Quality", active.quality.map((v) => label("quality", v)));
      if (f.lang.length > 1) html += chip("lang", "Language", active.lang);
      if (f.source.length > 1) html += chip("source", "Source", active.source.map((v) => label("source", v)));
      if (f.provider.length > 1) html += chip("provider", "Provider", active.provider);
      if (f.instant && f.instant < total) html += `<button type="button" class="dx-sb-btn dx-sb-toggle${s.instant ? " is-on" : ""}" data-toggle="instant">⚡ Instant</button>`;
      if (f.hdr && f.hdr < total) html += `<button type="button" class="dx-sb-btn dx-sb-toggle${s.hdr ? " is-on" : ""}" data-toggle="hdr">HDR / DV</button>`;
      const filtered = active.quality.length || active.lang.length || active.source.length || active.provider.length || s.instant || s.hdr;
      html += `<span class="dx-sb-count">${shown === total ? `${total} streams` : `${shown} of ${total}`}</span>`;
      if (filtered || s.sort !== "default") html += `<button type="button" class="dx-sb-reset" data-act="reset">Reset</button>`;
      html += `</div>`;

      if (this.open) {
        const opts = this.open === "sort"
          ? SORTS.map(([k, l]) => ({ v: k, l, on: s.sort === k }))
          : f[this.open].map(([v, l, n]) => ({ v, l, n, on: (active[this.open] || []).includes(v) }));
        html += `<div class="dx-sb-menu" data-for="${this.open}">` + opts.map((o) =>
          `<button type="button" class="dx-sb-opt${o.on ? " is-on" : ""}" data-val="${esc(o.v)}"><span class="dx-sb-check">${o.on ? ICONS.check : ""}</span><span class="dx-sb-label">${esc(o.l)}</span>${o.n ? `<span class="dx-sb-n">${o.n}</span>` : ""}</button>`
        ).join("") + `</div>`;
      }
      bar.innerHTML = html;
    },

    onClick(e) {
      const t = e.target.closest("button");
      if (!t) return;
      e.preventDefault();
      e.stopPropagation();
      const s = this.state;
      if (t.dataset.menu) {
        this.open = this.open === t.dataset.menu ? null : t.dataset.menu;
        sfx.play("menu", 0.8);
      } else if (t.dataset.toggle) {
        s[t.dataset.toggle] = !s[t.dataset.toggle];
        sfx.play(s[t.dataset.toggle] ? "toggleOn" : "toggleOff");
      } else if (t.dataset.act === "reset") {
        Object.assign(s, { sort: "default", quality: [], lang: [], source: [], provider: [], instant: false, hdr: false });
        this.open = null;
        sfx.play("tick", 1.2);
      } else if (t.dataset.val !== undefined) {
        const key = t.closest(".dx-sb-menu").dataset.for;
        if (key === "sort") {
          s.sort = t.dataset.val;
          this.open = null;
        } else {
          const set = new Set(s[key]);
          set.has(t.dataset.val) ? set.delete(t.dataset.val) : set.add(t.dataset.val);
          s[key] = [...set];
        }
        sfx.play("tick", 1.2);
      }
      this.save();
      this.sig = "";
      this.ensure();
    },

    closeMenu(e) {
      if (!this.open) return;
      if (e && e.target instanceof Element && e.target.closest(".dx-streambar")) return;
      this.open = null;
      this.sig = "";
      this.ensure();
    },
  };

  function onStreamDocClick(e) {
    const t = e.target instanceof Element ? e.target : null;
    const reset = t && t.closest(".dx-stream-empty [data-act='reset']");
    if (reset) streamTools.onClick({ target: reset, preventDefault() {}, stopPropagation() {} });
    else streamTools.closeMenu(e);
  }

  // ---------------------------------------------------------------------------
  // Seek bar: Netflix-style hover preview (thumbnail + time), hover fill, time remaining
  // ---------------------------------------------------------------------------

  function formatClock(seconds) {
    const s = Math.max(0, Math.floor(seconds));
    const h = Math.floor(s / 3600);
    const m = Math.floor((s % 3600) / 60);
    const sec = String(s % 60).padStart(2, "0");
    return h ? `${h}:${String(m).padStart(2, "0")}:${sec}` : `${m}:${sec}`;
  }

  const scrub = {
    slider: null,
    ui: null,
    preview: null,      // hidden <video> used only to grab frames
    frames: new Map(),  // bucket (s) -> canvas
    want: null,
    busy: false,
    timer: null,
    hovering: false,
    BUCKET: 4,          // seconds per cached frame
    MAX_FRAMES: 90,

    ensure() {
      if (currentRoute() !== "player") { this.teardown(); return; }
      const root = document.querySelector('[class*="player-container"]');
      const seek = root && root.querySelector('[class*="seek-bar-container"]');
      const slider = seek && seek.querySelector('[class*="slider-container"]');
      if (!slider) return;
      if (slider !== this.slider || !this.ui || !this.ui.isConnected) {
        this.teardown();
        this.attach(slider);
      }
      // Netflix counts down: switch Stremio's right-hand clock to "time remaining" once per playback
      if (settings.remainingTime) {
        const clock = seek.querySelector(':scope > [class*="button-container"]');
        if (clock && !clock.dataset.dxRemaining) {
          clock.dataset.dxRemaining = "1";
          clock.click();
        }
      }
    },

    video() {
      return document.querySelector('[class*="player-container"] video');
    },

    attach(slider) {
      this.slider = slider;
      const ui = document.createElement("div");
      ui.className = "dx-scrub";
      ui.innerHTML = `
        <div class="dx-scrub-fill"></div>
        <div class="dx-scrub-tip">
          <div class="dx-scrub-frame"><canvas width="320" height="180"></canvas></div>
          <div class="dx-scrub-time"></div>
        </div>`;
      slider.append(ui);
      this.ui = ui;
      this.canvas = ui.querySelector("canvas");
      slider.addEventListener("pointerenter", this.onEnter);
      slider.addEventListener("pointerleave", this.onLeave);
      window.addEventListener("pointermove", this.onMove, { passive: true });
    },

    teardown() {
      clearTimeout(this.timer);
      if (this.slider) {
        this.slider.removeEventListener("pointerenter", this.onEnter);
        this.slider.removeEventListener("pointerleave", this.onLeave);
      }
      window.removeEventListener("pointermove", this.onMove);
      if (this.ui) this.ui.remove();
      if (this.preview) {
        // stop any network activity from the frame grabber
        this.preview.removeAttribute("src");
        this.preview.load();
        this.preview = null;
      }
      this.frames.clear();
      this.slider = null;
      this.ui = null;
      this.want = null;
      this.busy = false;
      this.hovering = false;
    },

    onEnter: () => { scrub.hovering = true; },
    onLeave: () => {
      scrub.hovering = false;
      if (!document.documentElement.className.includes("active-slider-within")) scrub.hide();
    },

    onMove: (e) => {
      const self = scrub;
      if (!self.slider || !self.ui) return;
      const dragging = document.documentElement.className.includes("active-slider-within");
      if (!self.hovering && !dragging) return;
      // same maths Stremio uses to turn the cursor into a time, so everything lines up exactly
      const r = self.slider.getBoundingClientRect();
      const frac = Math.min(Math.max((e.clientX - r.left) / r.width, 0), 1);
      self.show(frac, r);
    },

    hide() {
      if (this.ui) this.ui.classList.remove("is-on");
      clearTimeout(this.timer);
    },

    show(frac, rect) {
      const v = this.video();
      const duration = v && isFinite(v.duration) ? v.duration : null;
      if (!duration) { this.hide(); return; }
      const t = frac * duration;
      const ui = this.ui;
      ui.classList.add("is-on");

      // lighter fill from the playhead to the cursor (like the buffered bar)
      // only ahead of the playhead — behind it the red progress already says enough
      const played = Math.min(1, (v.currentTime || 0) / duration);
      const fill = ui.firstElementChild;
      fill.style.left = (played * 100) + "%";
      fill.style.width = (Math.max(0, frac - played) * 100) + "%";

      // tooltip follows the cursor but never leaves the player
      const tip = ui.querySelector(".dx-scrub-tip");
      const playerRect = this.slider.closest('[class*="player-container"]').getBoundingClientRect();
      const half = tip.offsetWidth / 2 || 130;
      const x = rect.left + frac * rect.width;
      const clamped = Math.min(Math.max(x, playerRect.left + half + 12), playerRect.right - half - 12);
      tip.style.left = (clamped - rect.left) + "px";
      ui.querySelector(".dx-scrub-time").textContent = formatClock(t);

      if (settings.seekPreviews) this.requestFrame(t);
      else ui.classList.remove("has-frame");
    },

    // ---- thumbnails ------------------------------------------------------------
    source() {
      const v = this.video();
      const src = v && (v.currentSrc || v.src);
      // Only direct files/streams can be opened twice; MSE/HLS blobs can't
      return src && /^https?:/i.test(src) ? src : null;
    },

    requestFrame(t) {
      const bucket = Math.round(t / this.BUCKET) * this.BUCKET;
      const cached = this.frames.get(bucket);
      if (cached) {
        this.paint(cached);
        return;
      }
      this.want = bucket;
      clearTimeout(this.timer);
      // wait for the cursor to settle a moment, so sweeping across the bar doesn't fire dozens of seeks
      this.timer = setTimeout(() => this.fetchFrame(), 110);
    },

    fetchFrame() {
      if (this.busy || this.want === null || !this.ui) return;
      const src = this.source();
      if (!src) { this.ui.classList.remove("has-frame"); return; }
      if (!this.preview) {
        const p = document.createElement("video");
        p.muted = true;
        p.preload = "metadata";
        p.playsInline = true;
        p.src = src;
        p.addEventListener("seeked", () => this.onSeeked());
        p.addEventListener("error", () => { this.preview = null; });
        this.preview = p;
      }
      const target = this.want;
      this.busy = true;
      this.pendingBucket = target;
      const go = () => { try { this.preview.currentTime = Math.max(0.1, target); } catch (_) { this.busy = false; } };
      if (this.preview.readyState >= 1) go();
      else this.preview.addEventListener("loadedmetadata", go, { once: true });
      // never get stuck if a seek doesn't come back
      clearTimeout(this.stuck);
      this.stuck = setTimeout(() => { this.busy = false; }, 4000);
    },

    onSeeked() {
      clearTimeout(this.stuck);
      const p = this.preview;
      if (!p || !this.ui) return;
      const c = document.createElement("canvas");
      const w = 320;
      const h = Math.round(w * ((p.videoHeight || 9) / (p.videoWidth || 16)));
      c.width = w;
      c.height = h;
      try { c.getContext("2d").drawImage(p, 0, 0, w, h); } catch (_) { /* frame not ready */ }
      this.frames.set(this.pendingBucket, c);
      if (this.frames.size > this.MAX_FRAMES) this.frames.delete(this.frames.keys().next().value);
      if (this.want === this.pendingBucket) this.paint(c);
      this.busy = false;
      if (this.want !== null && this.want !== this.pendingBucket && !this.frames.has(this.want)) this.fetchFrame();
    },

    paint(frame) {
      if (!this.ui) return;
      const c = this.canvas;
      if (c.width !== frame.width || c.height !== frame.height) {
        c.width = frame.width;
        c.height = frame.height;
      }
      c.getContext("2d").drawImage(frame, 0, 0);
      this.ui.classList.add("has-frame");
    },
  };

  // ---------------------------------------------------------------------------
  // UI sounds — synthesised once into buffers (no audio files), then played instantly
  // ---------------------------------------------------------------------------

  const SOUNDS = {
    // keyboard focus moving between items
    tick: { dur: 0.12, build: (s) => { s.tone("sine", 2100, 1750, 0, 0.035, 0.22, 0.0015); s.noise(5200, 1.2, 0, 0.012, 0.05); } },
    // nav tab switch
    tab: { dur: 0.3, build: (s) => { s.tone("triangle", 540, 400, 0, 0.09, 0.32, 0.002); s.tone("sine", 1080, 800, 0, 0.04, 0.06, 0.002); s.noise(2600, 1.5, 0, 0.014, 0.05); } },
    // opening a title / pressing a primary button
    select: { dur: 0.4, build: (s) => { s.tone("sine", 330, 470, 0, 0.13, 0.26, 0.004); s.tone("sine", 660, 940, 0.01, 0.1, 0.08, 0.004); s.noise(3000, 1.2, 0, 0.01, 0.035); } },
    // hover preview opening
    pop: { dur: 0.28, build: (s) => { s.tone("sine", 260, 430, 0, 0.075, 0.22, 0.003); s.tone("sine", 860, 860, 0.012, 0.05, 0.035, 0.004); } },
    // carousel arrows / billboard dots
    swipe: { dur: 0.32, build: (s) => { s.sweep(500, 2600, 0, 0.17, 0.32); s.tone("sine", 320, 280, 0, 0.05, 0.05, 0.003); } },
    // added to My List
    confirm: { dur: 0.6, build: (s) => { s.bell(659.25, 0, 0.2); s.bell(987.77, 0.075, 0.2); } },
    // removed from My List
    remove: { dur: 0.55, build: (s) => { s.bell(880, 0, 0.16); s.bell(587.33, 0.07, 0.16); } },
    // player
    play: { dur: 0.3, build: (s) => { s.tone("triangle", 190, 270, 0, 0.08, 0.3, 0.002); s.tone("sine", 540, 540, 0.005, 0.05, 0.06, 0.003); s.noise(2400, 1.4, 0, 0.012, 0.05); } },
    pause: { dur: 0.3, build: (s) => { s.tone("triangle", 270, 180, 0, 0.09, 0.3, 0.002); s.noise(2000, 1.4, 0, 0.012, 0.05); } },
    seek: { dur: 0.25, build: (s) => { s.sweep(900, 3200, 0, 0.09, 0.2); s.tone("sine", 1500, 1300, 0, 0.03, 0.2, 0.0015); } },
    // panels / menus / toggles
    menu: { dur: 0.25, build: (s) => { s.tone("sine", 420, 640, 0, 0.06, 0.16, 0.003); s.noise(3500, 1.5, 0, 0.008, 0.03); } },
    toggleOn: { dur: 0.25, build: (s) => { s.tone("sine", 880, 880, 0, 0.045, 0.14, 0.002); s.tone("sine", 1318.5, 1318.5, 0.045, 0.06, 0.14, 0.002); } },
    toggleOff: { dur: 0.25, build: (s) => { s.tone("sine", 1174.7, 1174.7, 0, 0.045, 0.12, 0.002); s.tone("sine", 784, 784, 0.045, 0.06, 0.12, 0.002); } },
  };

  const VOLUMES = { subtle: 0.3, normal: 0.55, loud: 0.85 };

  const sfx = {
    ctx: null,
    out: null,
    buffers: {},
    ready: null,
    last: {},

    ensure() {
      if (this.ready) return this.ready;
      const Ctx = window.AudioContext || window.webkitAudioContext;
      if (!Ctx || typeof OfflineAudioContext === "undefined") return (this.ready = Promise.resolve(false));
      try {
        this.ctx = new Ctx({ latencyHint: "interactive" });
        this.out = this.ctx.createGain();
        this.out.connect(this.ctx.destination);
      } catch (_) {
        return (this.ready = Promise.resolve(false));
      }
      this.ready = (async () => {
        const verb = this.impulse(0.45);
        for (const [name, design] of Object.entries(SOUNDS)) {
          try { this.buffers[name] = await this.render(design, verb); } catch (err) { log("sound render failed", name, err); }
        }
        return true;
      })();
      return this.ready;
    },

    // Short, darkened stereo room so clicks sound "placed" rather than synthetic
    impulse(seconds) {
      const sr = 48000;
      const len = Math.floor(sr * seconds);
      const data = [new Float32Array(len), new Float32Array(len)];
      let seed = 1;
      const rand = () => ((seed = (seed * 16807) % 2147483647) / 2147483647) * 2 - 1;
      for (const ch of data) {
        let lp = 0;
        for (let i = 0; i < len; i++) {
          lp += 0.35 * (rand() - lp);
          ch[i] = lp * Math.exp(-i / (sr * 0.09));
        }
      }
      return data;
    },

    async render(design, verbData) {
      const sr = 48000;
      const oc = new OfflineAudioContext(2, Math.ceil((design.dur + 0.35) * sr), sr);
      const dry = oc.createGain();
      const verb = oc.createConvolver();
      const ir = oc.createBuffer(2, verbData[0].length, sr);
      ir.copyToChannel(verbData[0], 0);
      ir.copyToChannel(verbData[1], 1);
      verb.buffer = ir;
      const wet = oc.createGain();
      wet.gain.value = 0.18;
      dry.connect(oc.destination);
      dry.connect(verb).connect(wet).connect(oc.destination);

      const env = (g, t, attack, length, peak) => {
        g.gain.setValueAtTime(0.0001, t);
        g.gain.exponentialRampToValueAtTime(peak, t + attack);
        g.gain.exponentialRampToValueAtTime(0.0001, t + length);
      };
      const kit = {
        tone(type, f0, f1, at, length, peak, attack) {
          const o = oc.createOscillator();
          const g = oc.createGain();
          o.type = type;
          o.frequency.setValueAtTime(f0, at);
          if (f1 !== f0) o.frequency.exponentialRampToValueAtTime(f1, at + length);
          env(g, at, attack, length, peak);
          o.connect(g).connect(dry);
          o.start(at);
          o.stop(at + length + 0.02);
        },
        noise(freq, q, at, length, peak) {
          const b = oc.createBuffer(1, Math.ceil(length * sr) + 64, sr);
          const d = b.getChannelData(0);
          for (let i = 0; i < d.length; i++) d[i] = Math.random() * 2 - 1;
          const src = oc.createBufferSource();
          src.buffer = b;
          const f = oc.createBiquadFilter();
          f.type = "bandpass";
          f.frequency.value = freq;
          f.Q.value = q;
          const g = oc.createGain();
          env(g, at, 0.0008, length, peak);
          src.connect(f).connect(g).connect(dry);
          src.start(at);
        },
        sweep(f0, f1, at, length, peak) {
          const b = oc.createBuffer(1, Math.ceil(length * sr) + 64, sr);
          const d = b.getChannelData(0);
          for (let i = 0; i < d.length; i++) d[i] = Math.random() * 2 - 1;
          const src = oc.createBufferSource();
          src.buffer = b;
          const f = oc.createBiquadFilter();
          f.type = "bandpass";
          f.Q.value = 0.9;
          f.frequency.setValueAtTime(f0, at);
          f.frequency.exponentialRampToValueAtTime(f1, at + length);
          const g = oc.createGain();
          g.gain.setValueAtTime(0.0001, at);
          g.gain.exponentialRampToValueAtTime(peak, at + length * 0.45);
          g.gain.exponentialRampToValueAtTime(0.0001, at + length);
          src.connect(f).connect(g).connect(dry);
          src.start(at);
        },
        // soft bell: fundamental + quiet inharmonic partials
        bell(freq, at, peak) {
          kit.tone("sine", freq, freq, at, 0.42, peak, 0.004);
          kit.tone("sine", freq * 2.01, freq * 2.01, at, 0.22, peak * 0.22, 0.003);
          kit.tone("sine", freq * 3.98, freq * 3.98, at, 0.12, peak * 0.07, 0.002);
        },
      };
      design.build(kit);
      return oc.startRendering();
    },

    play(name, gain = 1) {
      if (!settings.uiSounds) return;
      const now = performance.now();
      if (now - (this.last[name] || 0) < 45) return; // no machine-gun repeats
      this.last[name] = now;
      if (!this.ctx) {
        this.ensure().then((ok) => ok && this.play(name, gain));
        this.last[name] = 0;
        return;
      }
      const buffer = this.buffers[name];
      if (!buffer) return;
      if (this.ctx.state === "suspended") this.ctx.resume().catch(() => {});
      const src = this.ctx.createBufferSource();
      src.buffer = buffer;
      const g = this.ctx.createGain();
      g.gain.value = (VOLUMES[settings.soundVolume] ?? VOLUMES.subtle) * gain;
      src.connect(g).connect(this.out);
      src.start();
    },
  };

  // Map interactions to sounds with one capturing listener (cheap, and works for stock UI too)
  let lastKeyNav = 0;
  function onSoundClick(e) {
    if (!settings.uiSounds) return;
    const t = e.target;
    if (!(t instanceof Element)) return;
    if (t.closest("[data-list]")) return; // My List plays its own confirm/remove
    if (t.closest('[class*="control-bar-buttons-container"] > [class*="control-bar-button-"]:first-child')) return; // play/pause: video events
    if (t.closest(".dx-seek")) return sfx.play("seek");
    if (t.closest('nav[class*="vertical-nav-bar"] a')) return sfx.play("tab");
    if (t.closest(".dx-arrow, .dx-hero-dot")) return sfx.play("swipe");
    if (t.closest(".dx-btn-primary, .dx-round.is-primary")) return sfx.play("select");
    if (t.closest(".dx-btn, .dx-round, .dx-preview-media")) return sfx.play("select", 0.8);
    if (t.closest('[class*="meta-item-container"] a, [class*="meta-item-link"]')) return sfx.play("select", 0.85);
    if (t.closest('[class*="stream-container"], [class*="video-container"][class*="button-container"]')) return sfx.play("select", 0.85);
    const toggle = t.closest('[class*="toggle-container"]');
    if (toggle) return sfx.play(toggle.classList.contains("checked") ? "toggleOff" : "toggleOn");
    if (t.closest('[class*="control-bar-button-"], [class*="control-bar-buttons-menu-button"]')) return sfx.play("menu", 0.8);
    if (t.closest('[class*="menu-button-container"], [class*="multiselect-menu"] > [class*="button-container"], [class*="filter-button"]')) return sfx.play("menu");
    if (t.closest('[class*="language-option"], [class*="variant-option"], [class*="speed-button"], [class*="option-container"], [class*="chip"]')) return sfx.play("tick", 1.2);
  }

  function onSoundKey(e) {
    if (["Tab", "ArrowLeft", "ArrowRight", "ArrowUp", "ArrowDown"].includes(e.key)) lastKeyNav = performance.now();
  }

  function onSoundFocus(e) {
    // Only for keyboard/remote navigation — never on mouse clicks
    if (performance.now() - lastKeyNav > 150 || currentRoute() === "player") return;
    if (e.target instanceof Element && e.target.matches('a, button, [tabindex], [class*="button-container"]')) sfx.play("tick");
  }

  // ---------------------------------------------------------------------------
  // Main loop
  // ---------------------------------------------------------------------------

  let syncQueued = false;
  function scheduleSync() {
    if (syncQueued) return;
    syncQueued = true;
    setTimeout(() => {
      syncQueued = false;
      sync();
    }, 90);
  }

  function sync() {
    const steps = [updateRoute, brandTitle, () => player.ensure(), () => scrub.ensure()];
    if (currentRoute() === "detail") steps.push(() => streamTools.ensure());
    if (currentRoute() !== "player") {
      steps.push(() => hero.ensure(), () => carouselRows().forEach(enhanceRow), syncCards);
    }
    // One failing step must never stop the others
    for (const step of steps) {
      try { step(); } catch (err) { log("sync step failed", err); }
    }
  }

  const mo = new MutationObserver((records) => {
    for (const r of records) {
      // Ignore changes we made ourselves
      if (r.target.closest && r.target.closest(".dx-hero, .dx-preview, .dx-row-pages, .dx-wide-art, .dx-player-title, .dx-player-flash, .dx-streambar, .dx-stream-empty, .dx-scrub")) continue;
      scheduleSync();
      return;
    }
  });

  const onResize = () => {
    preview.close(true);
    carouselRows().forEach(updateArrows);
  };
  const onOver = (e) => preview.onOver(e);
  const onOut = (e) => preview.onOut(e);
  const onHash = () => { updateRoute(); scheduleSync(); };
  const onTitle = new MutationObserver(brandTitle);

  function start() {
    // loadSettings applies the cached settings synchronously, so the intro sees the right accent/sound
    const loading = loadSettings();
    splash();
    loading.finally(scheduleSync);
    mo.observe(document.getElementById("app") || document.body, { childList: true, subtree: true });
    const titleEl = document.querySelector("title");
    if (titleEl) onTitle.observe(titleEl, { childList: true, characterData: true, subtree: true });
    document.addEventListener("scroll", onScroll, { capture: true, passive: true });
    document.addEventListener("mouseover", onOver, { passive: true });
    document.addEventListener("mouseout", onOut, { passive: true });
    window.addEventListener("hashchange", onHash);
    window.addEventListener("resize", onResize);
    document.addEventListener("visibilitychange", onHash);
    document.addEventListener("click", onSoundClick, true);
    document.addEventListener("click", onStreamDocClick, true);
    document.addEventListener("keydown", onSoundKey, true);
    document.addEventListener("focusin", onSoundFocus, true);
    // Prepare the sounds after the intro so they never compete with it
    setTimeout(() => { if (settings.uiSounds) sfx.ensure(); }, 4500);
    sync();
    log("ready");
  }

  window.__dxbi = {
    settings,
    sync,
    sfx,
    destroy() {
      mo.disconnect();
      io.disconnect();
      onTitle.disconnect();
      document.removeEventListener("scroll", onScroll, { capture: true });
      document.removeEventListener("mouseover", onOver);
      document.removeEventListener("mouseout", onOut);
      window.removeEventListener("hashchange", onHash);
      window.removeEventListener("resize", onResize);
      document.removeEventListener("visibilitychange", onHash);
      document.removeEventListener("click", onSoundClick, true);
      document.removeEventListener("click", onStreamDocClick, true);
      document.removeEventListener("keydown", onSoundKey, true);
      document.removeEventListener("focusin", onSoundFocus, true);
      if (sfx.ctx) sfx.ctx.close().catch(() => {});
      hero.remove();
      preview.close(true);
      preview.el?.remove();
      player.detach();
      scrub.teardown();
      document.querySelectorAll(".dx-arrow, .dx-row-pages, .dx-badge, .dx-wide-art, .dx-splash, .dx-seek, .dx-player-title, .dx-player-flash, .dx-streambar, .dx-stream-empty").forEach((n) => n.remove());
      document.querySelectorAll(".dx-sortable").forEach((l) => streamTools.reset(l));
      document.querySelectorAll("[data-dx-key]").forEach((n) => { delete n.dataset.dxKey; });
    },
  };

  if (document.body) start();
  else document.addEventListener("DOMContentLoaded", start, { once: true });

  // ---------------------------------------------------------------------------
  // Intro film: 1920x1080, 60 fps, AV1 + stereo Opus score, ~265 KB. Rendered procedurally (see /tools in the repo).
  // ---------------------------------------------------------------------------
  function introVideoData() {
    return "";
  }
})();
